// npm install --save-dev eslint-plugin-security eslint-plugin-no-unsanitized

// .eslintrc.js — add security rules
module.exports = {
  plugins: ['security', 'no-unsanitized'],
  extends: [
    'plugin:security/recommended',
  ],
  rules: {
    // Flag uses of eval() — almost never needed, often exploitable
    'no-eval': 'error',
    // Flag innerHTML assignments — potential XSS
    'no-unsanitized/method': 'error',
    'no-unsanitized/property': 'error',
    // Flag hardcoded secrets — catches 'password: "abc123"' patterns
    'security/detect-possible-timing-attacks': 'error',
    // Flag regex that could cause ReDoS (Catastrophic Backtracking)
    'security/detect-unsafe-regex': 'warn',
    // Flag child_process.exec with non-literal strings
    'security/detect-child-process': 'error',
    // Flag non-literal require() calls
    'security/detect-non-literal-require': 'warn',
  },
};

// Add to package.json scripts:
// "lint:security": "eslint . --ext .ts,.js --rule 'security/detect-object-injection: error'"

// In GitHub Actions:
// - name: Security lint
//   run: npm run lint:security

